-- ======================================================================
--  IRON LEAGUE — who somebody is, when you tap their face
--
--  Paste the whole file into the Supabase SQL editor and press RUN, or apply
--  it over the API. Safe to run twice. Create-only: one column and four
--  functions, nothing changes shape, nothing is dropped, NOTHING LOGGED IS
--  TOUCHED and no points move.
--
--  GENERATED by tools/build_card_migration.py, which lifts the functions
--  below out of supabase/schema.sql. Edit there and re-run it, never here.
--
--  WHY
--  Tapping a NAME opens that person's week, which is what you want when you
--  are reading a board. Tapping their FACE opens who they are, which is what
--  you want when somebody you do not recognise is above you -- and on a
--  campus, that is most of them.
--
--  WHAT IT ADDS
--  · profiles.bio -- one line, 140 characters, written by the person.
--  · set_bio(), which trims it and bounds it server-side rather than
--    trusting a client, and stores an empty one as null.
--  · player_card(), the card itself.
--  · admin_bios() and admin_clear_bio(), because a bio is the only free text
--    in this app that strangers read, and "the admin can delete the whole
--    account" is not a proportionate answer to a rude sentence.
--
--  THE PART THAT IS NOT OBVIOUS
--  This is a FUNCTION and not a wider league_leaderboard(), for two reasons.
--  A board is polled every 25 seconds by everybody with the app open and
--  carries a row per member, so a bio on it would be paid for by every
--  member of every league on every poll; a card is read once, when a finger
--  lands on a face.
--
--  And `profiles` is readable only for your own row since
--  shut-the-side-door.sql -- deliberately, because that row carries a
--  restore code. So a card cannot be a SELECT; it has to be something that
--  CHOOSES what it returns. player_card() returns no restore code, no
--  bodyweight and no account id, and its WHERE clause is what stops it being
--  a way to read strangers: you see somebody you share a league with, or you
--  see nothing.
--
--  ORDER OF DEPLOY: this file first, the app second. An app that has not
--  updated never calls any of it.
-- ======================================================================
begin;
set local check_function_bodies = off;

-- ------------------------------------------------------- the column ---
alter table public.profiles add column if not exists bio text;
alter table public.profiles drop constraint if exists profiles_bio_len;
alter table public.profiles add constraint profiles_bio_len
  check (bio is null or char_length(bio) <= 140);

-- --------------------------------------------------------------- set_bio ---
create or replace function public.set_bio(p_bio text)
returns public.profiles language plpgsql security definer set search_path = public as $fn$
declare me uuid := public.my_profile_id(); row public.profiles;
begin
  if me is null then raise exception 'NO_PROFILE'; end if;
  if char_length(btrim(coalesce(p_bio, ''))) > 140 then
    raise exception 'BIO_TOO_LONG';
  end if;
  update public.profiles set bio = nullif(btrim(coalesce(p_bio, '')), '')
   where id = me returning * into row;
  return row;
end $fn$;

-- ----------------------------------------------------------- player_card ---
-- DROP, not CREATE OR REPLACE. `create or replace` cannot change a return
-- type, so the day a column is added to this card every replay of this file
-- fails with "cannot change return type of existing function" -- which is
-- exactly what happened when the social handles went on. A migration that
-- stops being runnable is a migration that has quietly become a landmine for
-- whoever rebuilds next.
drop function if exists public.player_card(uuid) cascade;
create function public.player_card(p_profile uuid)
returns table (profile_id uuid, display_name text, avatar text, banner text,
               name_color text, frame text, bio text,
               pinned_badges text[], lifetime numeric, joined_at timestamptz)
language sql stable security definer set search_path = public as $fn$
  select p.id, p.display_name, p.avatar, p.banner, p.name_color, p.frame,
         p.bio, p.pinned_badges,
         coalesce((select sum(public.tier_points(x.raw, x.cap))
                   from (select sum(o.points) as raw, max(e.cap) as cap
                         from (select distinct on (w.group_id)
                                      w.group_id, w.exercise_key, w.week_start, w.points
                               from public.workouts w
                               where w.profile_id = p.id
                               order by w.group_id, w.league_id) o
                         left join public.exercises e on e.key = o.exercise_key
                         group by o.week_start, o.exercise_key) x), 0)::numeric,
         (select min(m.joined_at) from public.league_members m where m.profile_id = p.id)
  from public.profiles p
  where p.id = p_profile
    and (p.user_id = auth.uid() or public.shares_league_with(p.id))
$fn$;

-- ------------------------------------------------------------ admin_bios ---
create or replace function public.admin_bios()
returns table (profile_id uuid, display_name text, bio text)
language sql stable security definer set search_path = public as $fn$
  select p.id, p.display_name, p.bio
  from public.profiles p
  where public.is_admin() and p.bio is not null
  order by p.display_name
$fn$;

-- ------------------------------------------------------- admin_clear_bio ---
create or replace function public.admin_clear_bio(p_profile uuid)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if not public.is_admin() then raise exception 'Not allowed'; end if;
  update public.profiles set bio = null where id = p_profile;
end $fn$;

-- -------------------------------------------------------- grants ---
revoke all on function public.set_bio(text)                 from public, anon;
revoke all on function public.player_card(uuid)             from public, anon;
revoke all on function public.admin_clear_bio(uuid)         from public, anon;
revoke all on function public.admin_bios()                  from public, anon;
grant execute on function public.set_bio(text)                 to authenticated;
grant execute on function public.player_card(uuid)             to authenticated;
grant execute on function public.admin_clear_bio(uuid)         to authenticated;
grant execute on function public.admin_bios()                  to authenticated;

commit;

